import { expect, test } from '@playwright/test';
import { setUp } from './fixtures';

/**
 * The docs' screenshots and the README's GIF, regenerated by
 * `task ui:screenshots`. Skipped unless SCREENSHOTS_DIR is set.
 */
const DIR = process.env.SCREENSHOTS_DIR;
test.skip(!DIR, 'SCREENSHOTS_DIR is not set');
test.use({ viewport: { width: 1280, height: 800 } });

const VIEWS = [
  { name: 'home', path: '/', loggedIn: false, ready: 'ProxyAuthK8S' },
  { name: 'clusters', path: '/', loggedIn: true, ready: 'stopped' },
  { name: 'cli', path: '/cli', loggedIn: true, ready: 'kubectl plugin' },
  {
    name: 'callback',
    path: '/auth/callback/team/prod?code=c&state=s',
    loggedIn: true,
    ready: 'Tokens',
  },
];

for (const theme of ['dark', 'light'] as const) {
  for (const view of VIEWS) {
    test(`${view.name} (${theme})`, async ({ page, browserName }) => {
      test.skip(browserName !== 'chromium', 'one browser is enough');
      await setUp(page, { theme, loggedIn: view.loggedIn, locale: 'en' });
      await page.goto(view.path);
      await expect(page.getByText(view.ready).first()).toBeVisible();
      // The start-up notices would cover the view.
      const dismiss = page.getByRole('button', { name: 'Dismiss' });
      for (let i = 0; i < 5 && (await dismiss.count()) > 0; i++)
        await dismiss.first().click();
      await page.waitForTimeout(300);
      await page.screenshot({ path: `${DIR}/${view.name}-${theme}.png` });
    });
  }
}

/** The README's flow: pick a cluster, switch the theme, copy its URL. */
test('flow', async ({ browser, browserName, baseURL }) => {
  test.skip(browserName !== 'chromium', 'one browser is enough');
  const size = { width: 1000, height: 640 };
  const context = await browser.newContext({
    baseURL,
    viewport: size,
    recordVideo: { dir: `${DIR}/video`, size },
  });
  await context.grantPermissions(['clipboard-read', 'clipboard-write']);
  const page = await context.newPage();
  await setUp(page, { theme: 'dark', loggedIn: true, locale: 'en' });
  await page.goto('/');
  await expect(page.getByText('stopped').first()).toBeVisible();
  await page.waitForTimeout(900);
  await page.getByRole('button', { name: /Select\s+dev/ }).click();
  await page.waitForTimeout(1200);
  await page.getByRole('button', { name: 'Settings' }).click();
  await page.waitForTimeout(700);
  await page.getByRole('button', { name: 'Light' }).click();
  await page.keyboard.press('Escape');
  await page.waitForTimeout(1000);
  await page.getByRole('button', { name: 'Copy the URL' }).click();
  await page.waitForTimeout(1800);
  await context.close();
  await page.video()?.saveAs(`${DIR}/flow.webm`);
});
